#include <string>

class Solution {
public:
    int numSteps(std::string s) {
        int steps = 0, carry = 0;
        for (int i = (int)s.size() - 1; i > 0; --i) {
            int digit = (s[i] - '0') + carry;
            if (digit % 2 == 1) {
                steps += 2;
                carry = 1;
            } else {
                steps += 1;
            }
        }
        return steps + carry;
    }
};

class Solution {
    public int numSteps(String s) {
        int steps = 0, carry = 0;
        for (int i = s.length() - 1; i > 0; i--) {
            int digit = (s.charAt(i) - '0') + carry;
            if (digit % 2 == 1) {
                steps += 2;
                carry = 1;
            } else {
                steps += 1;
            }
        }
        return steps + carry;
    }
}

var numSteps = function(s) {
    let steps = 0, carry = 0;
    for (let i = s.length - 1; i > 0; i--) {
        const digit = (s.charCodeAt(i) - 48) + carry;
        if (digit % 2 === 1) {
            steps += 2;
            carry = 1;
        } else {
            steps += 1;
        }
    }
    return steps + carry;
};
